cypress_script:
describe('File Upload Functionality', () => {
  it('should successfully upload a file', () => {
    cy.visit('https://the-internet.herokuapp.com/upload');
    cy.get('input#file-upload').attachFile('example.txt');
    cy.get('input#file-submit').click();
    cy.url().should('include', '/upload');
  });

  it('should not change the URL when no file is uploaded', () => {
    cy.visit('https://the-internet.herokuapp.com/upload');
    cy.get('input#file-submit').click();
    cy.url().should('include', '/upload');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('File Upload Functionality', () => {
  test('should successfully upload a file', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/upload');
    await page.setInputFiles('input#file-upload', 'example.txt');
    await page.click('input#file-submit');
    await expect(page).toHaveURL(/.*upload/);
  });

  test('should not change the URL when no file is uploaded', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/upload');
    await page.click('input#file-submit');
    await expect(page).toHaveURL(/.*upload/);
  });
});
